INSERT INTO training_sections (id, course_id, title, description, ord) VALUES ('cyber_s1', 'cyber', 'BAGIAN 1 — SANDI ITU KEREN', '"Kamu sudah jadi hacker sejak SD tanpa sadar"', 1) ON CONFLICT(id) DO UPDATE SET title = EXCLUDED.title;
INSERT INTO training_sections (id, course_id, title, description, ord) VALUES ('cyber_s2', 'cyber', 'BAGIAN 2 — MORSE CODE: SANDI PALING LEGENDARIS', '"Dipakai pilot, tentara, dan astronot — sekarang kamu juga"', 2) ON CONFLICT(id) DO UPDATE SET title = EXCLUDED.title;
INSERT INTO training_sections (id, course_id, title, description, ord) VALUES ('cyber_s3', 'cyber', 'BAGIAN 3 — CAESAR CIPHER: SANDI YANG MENGUBAH DUNIA', '"Julius Caesar pakai ini 2000 tahun lalu — WhatsApp pakai versinya sekarang"', 3) ON CONFLICT(id) DO UPDATE SET title = EXCLUDED.title;
INSERT INTO training_sections (id, course_id, title, description, ord) VALUES ('cyber_s4', 'cyber', 'BAGIAN 4 — PASSWORD: KUNCIMU KE DUNIA DIGITAL', '"Password ''bismillah123'' kamu bisa ditembus dalam 0.001 detik"', 4) ON CONFLICT(id) DO UPDATE SET title = EXCLUDED.title;
INSERT INTO training_sections (id, course_id, title, description, ord) VALUES ('cyber_s5', 'cyber', 'BAGIAN 5 — PHISHING: JANGAN SAMPAI KETIPU', '"Hacker tidak selalu pakai kode — kadang cukup kirim pesan WA"', 5) ON CONFLICT(id) DO UPDATE SET title = EXCLUDED.title;
INSERT INTO training_sections (id, course_id, title, description, ord) VALUES ('cyber_s6', 'cyber', 'BAGIAN 6 — OSINT: CARA DETEKTIF DIGITAL BEKERJA', '"Dari foto selfie kamu, orang bisa tahu kamu ada di mana"', 6) ON CONFLICT(id) DO UPDATE SET title = EXCLUDED.title;
INSERT INTO training_sections (id, course_id, title, description, ord) VALUES ('cyber_s7', 'cyber', 'BAGIAN 7 — CARA INTERNET BEKERJA', '"Kamu pakai internet tiap hari tapi tau gak cara kerjanya?"', 7) ON CONFLICT(id) DO UPDATE SET title = EXCLUDED.title;
INSERT INTO training_sections (id, course_id, title, description, ord) VALUES ('cyber_s8', 'cyber', 'BAGIAN 8 — ENKRIPSI MODERN: SANDI YANG TAK BISA DIBOBOL', '"Enkripsi yang melindungi chat WA-mu lebih rumit dari soal UN"', 8) ON CONFLICT(id) DO UPDATE SET title = EXCLUDED.title;
INSERT INTO training_sections (id, course_id, title, description, ord) VALUES ('cyber_s9', 'cyber', 'BAGIAN 9 — SERANGAN SIBER & CARA BERTAHAN', '"Ini yang dilakukan hacker — dan cara kamu lawan mereka"', 9) ON CONFLICT(id) DO UPDATE SET title = EXCLUDED.title;
